var e = new RuleEngine();
e.Add("high", ctx => ctx["score"] > 50);
e.Add("even", ctx => ctx["score"] % 2 == 0);
var ctx = new Dictionary<string, int> { ["score"] = 60 };
var r = e.Evaluate(ctx);
Cj.Eq(string.Join(",", r), "high,even", "both pass in order");
ctx["score"] = 40;
Cj.Eq(string.Join(",", e.Evaluate(ctx)), "even", "re-evaluated against current ctx");
